// TH16 v1.00a Extra 最终Boss 第4非符（Boss4）。源 st07bs.ecl.txt:390-450，
// 依赖 Boss4_at（452-475）。Extra(rank4) 只实现源掩码 O 分支。
// 弹型别名取 transcribe/th16/touhou-bullets.ecl：源 etSprite(0,10,10) = TH16_SHARD / color10。
const TH16_SHARD: int = 512;
const BULLET_COLOR: int = 10;

const TIME_LIMIT: int = 3724;
const OPENING_BUFFER: int = 120;

// 源 Boss4_at：etAim(0,3)=固定方向环，etCount(3,3)，etSpeed(4,3) 层速 4/3.5/3，
// etAngle(%C,0)：每波整环基角加 ±8°（0.13962634rad），第二角实参为 0.0f（本段 %B 未使用）。
// 每波 3 路 × 3 层、每 3 帧一发，共 100 波；%C 在任务起始读一次 ANGLE_PLAYER。
// 出生点：etOffset(0,0,-24) 的出弹口 + (etDist 32 − ANIM 4×初速) 沿弹自身角度。
async sub volley(sign: int) {
    var a0: int = aim_player() as int;
    for n in 0..100 {
        var alpha: int = a0 + sign * ((n * 145636) / 100);
        for q in 0..3 {
            var spd: fx = 4fx - 0.5fx * q;
            var d: fx = 32fx - 4fx * spd;
            for i in 0..3 {
                var a: int = alpha + (i * 65536) / 3;
                var ang: angle = a as angle;
                _ = fire(TH16_SHARD, BULLET_COLOR,
                         $self_x + d * cos(ang),
                         $self_y - 24fx + d * sin(ang),
                         spd, ang, none, none);
            }
        }
        wait(3);
    }
}

// 源 moveRand(60,4,1.9)：方向按当时位置/玩家x抽一次，速度 1.9·(1−k/60)，
// 每帧按 moveLimit(0,128,240,64) 夹位置（方向内区 x±60、y112..144，实际界 x±120、y[96,160]）。
sub move_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * (60 - k) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    move_arm_next_step();
}

sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    move_begin(a as angle);
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        move_arm_next_step();
    }
}

async sub boss() {
    set_invuln(65535);
    set_hurtbox(20fx);   // 源 Boss 入口 setHurtbox(40,40)
    set_hitbox(24fx);    // 源 Boss 入口 setHitbox(48,48)，体碰保留
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);   // 源 movePosTime(60,4,0,128)
    wait(120);
    wait(60);
    loop {
        spawn volley(1);
        wait(100);
        move_rand();
        move_wait(60);
        spawn volley(-1);
        wait(100);
        move_rand();
        move_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13700, 0, 0, 0, boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);   // 段尾收掉真实敌，避免越过段结束继续发弹
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
